-- adobe_aep.experience_event, adobe_aep.journey_step_event
-- are append-only and carry no updated_at, so they take no trigger.

-- 8 partition children take no trigger of their own: a trigger on
-- the partitioned parent already fires for rows routed into them.

-- -------------------------------------------------------------------------
-- Change log.
-- -------------------------------------------------------------------------
CREATE TABLE adobe_aep._change_log (
    change_log_id   BIGINT       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    table_name      VARCHAR(63)  NOT NULL,
    operation       CHAR(1)      NOT NULL CHECK (operation IN ('I', 'U', 'D')),
    -- Text, not BIGINT: one log serves tables keyed by integer, bigint and
    -- composite business keys alike.
    row_key         VARCHAR(200) NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    changed_by      TEXT         NOT NULL DEFAULT current_user,
    -- Populated on delete only. Inserts and updates leave it null because
    -- the current row remains readable in the base table, and copying it
    -- would double the write volume of the busiest tables.
    old_row         JSONB
);

CREATE INDEX ix_adobe_aep_change_log_changed_at
    ON adobe_aep._change_log (changed_at);
CREATE INDEX ix_adobe_aep_change_log_table
    ON adobe_aep._change_log (table_name, changed_at);

COMMENT ON TABLE adobe_aep._change_log IS
    'Change capture for incremental extraction. Deletes are the reason this '
    'exists: a high-water-mark read of updated_at cannot see a removed row.';

CREATE OR REPLACE FUNCTION adobe_aep.log_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    -- TG_ARGV[0] names the key column, so one function serves every table.
    key_column TEXT := TG_ARGV[0];
    source_row JSONB;
BEGIN
    source_row := to_jsonb(COALESCE(OLD, NEW));

    INSERT INTO adobe_aep._change_log (table_name, operation, row_key, old_row)
    VALUES (
        TG_TABLE_NAME,
        CASE TG_OP WHEN 'INSERT' THEN 'I' WHEN 'UPDATE' THEN 'U' ELSE 'D' END,
        COALESCE(source_row ->> key_column, '(unknown)'),
        CASE WHEN TG_OP = 'DELETE' THEN source_row ELSE NULL END
    );

    RETURN COALESCE(NEW, OLD);
END;
$$;

COMMENT ON FUNCTION adobe_aep.log_change() IS
    'Generic change logger. Pass the key column name as the trigger argument.';

-- Applied to the master and financial tables, where a missed delete would
-- leave an orphan in the target model. Deliberately not applied to
-- append-only high-volume tables: the write volume would double for no
-- benefit, since nothing ever deletes from them.
CREATE TRIGGER trg_profile_change
    AFTER INSERT OR UPDATE OR DELETE ON adobe_aep.profile
    FOR EACH ROW EXECUTE FUNCTION adobe_aep.log_change('profile_id');
CREATE TRIGGER trg_identity_change
    AFTER INSERT OR UPDATE OR DELETE ON adobe_aep.identity
    FOR EACH ROW EXECUTE FUNCTION adobe_aep.log_change('identity_id');
CREATE TRIGGER trg_identity_graph_link_change
    AFTER INSERT OR UPDATE OR DELETE ON adobe_aep.identity_graph_link
    FOR EACH ROW EXECUTE FUNCTION adobe_aep.log_change('identity_graph_link_id');
CREATE TRIGGER trg_consent_record_change
    AFTER INSERT OR UPDATE OR DELETE ON adobe_aep.consent_record
    FOR EACH ROW EXECUTE FUNCTION adobe_aep.log_change('consent_record_id');
CREATE TRIGGER trg_segment_membership_change
    AFTER INSERT OR UPDATE OR DELETE ON adobe_aep.segment_membership
    FOR EACH ROW EXECUTE FUNCTION adobe_aep.log_change('profile_id');
CREATE TRIGGER trg_privacy_job_change
    AFTER INSERT OR UPDATE OR DELETE ON adobe_aep.privacy_job
    FOR EACH ROW EXECUTE FUNCTION adobe_aep.log_change('privacy_job_id');

-- -------------------------------------------------------------------------
-- Role separation.
--
-- The roles are created defensively because every schema grants to the same
-- three and the load order across schemas is not guaranteed.
-- -------------------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_app') THEN
        CREATE ROLE offball_app NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_analyst') THEN
        CREATE ROLE offball_analyst NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'offball_ingest') THEN
        CREATE ROLE offball_ingest NOLOGIN;
    END IF;
END;
$$;

GRANT USAGE ON SCHEMA adobe_aep TO offball_app, offball_analyst, offball_ingest;

-- The application needs everything.
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA adobe_aep
    TO offball_app;

-- Analysts and the ingestion job read.
GRANT SELECT ON ALL TABLES IN SCHEMA adobe_aep
    TO offball_analyst, offball_ingest;

COMMENT ON SCHEMA adobe_aep IS
    'Adobe Experience Platform -- unified profile, identity graph, '
    'experience events, segments, consent and journeys. System of record '
    'for fan behaviour and the identity resolution point across the other '
    'systems. Extract pattern: event stream for experience events, API '
    'for profile and segment state.';
